package com.szr.crosserp.packing.service;

import com.szr.crosserp.common.exception.ApiException;
import com.szr.crosserp.inventory.model.*;
import com.szr.crosserp.inventory.repository.InventoryAllocationRepository;
import com.szr.crosserp.inventory.service.InventoryPackingService;
import com.szr.crosserp.order.model.*;
import com.szr.crosserp.order.repository.*;
import com.szr.crosserp.packing.dto.PackingDtos.*;
import com.szr.crosserp.packing.model.*;
import com.szr.crosserp.packing.repository.*;
import com.szr.crosserp.user.model.User;
import com.szr.crosserp.user.repository.UserRepository;
import java.time.Instant;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class PackingCommandService {
    private static final List<String> ROLES=List.of("OWNER","PACKING");
    private final PackingTaskRepository tasks;private final PackingBoxRepository boxes;private final PackingBoxItemRepository boxItems;private final PackingEventRepository events;private final SalesOrderRepository orders;private final SalesOrderItemRepository orderItems;private final InventoryAllocationRepository allocations;private final InventoryPackingService inventory;private final UserRepository users;
    public PackingCommandService(PackingTaskRepository tasks,PackingBoxRepository boxes,PackingBoxItemRepository boxItems,PackingEventRepository events,SalesOrderRepository orders,SalesOrderItemRepository orderItems,InventoryAllocationRepository allocations,InventoryPackingService inventory,UserRepository users){this.tasks=tasks;this.boxes=boxes;this.boxItems=boxItems;this.events=events;this.orders=orders;this.orderItems=orderItems;this.allocations=allocations;this.inventory=inventory;this.users=users;}
    @Transactional public CommandResponse start(Long orderId,StartRequest request,String subject,List<String> roles){User actor=actor(subject,roles);SalesOrder order=orders.findById(orderId).orElseThrow(()->notFound("订单不存在"));if(tasks.findByOrderId(orderId).isPresent())throw conflict("PACKING_TASK_EXISTS","订单已有打包任务");if(order.getExternalStatus()==ExternalOrderStatus.CANCELED||order.isFulfillmentException())throw conflict("PACKING_ORDER_UNAVAILABLE","订单当前不可打包");requireFullyReserved(orderId);Instant now=Instant.now();PackingTask task=tasks.save(new PackingTask(number("PKT"),order,actor,now));events.save(new PackingEvent(task,PackingEventType.STARTED,actor,trim(request==null?null:request.reason()),now));return response(task);}
    @Transactional public CommandResponse addBox(Long taskId,SaveBoxRequest request,String subject,List<String> roles){User actor=actor(subject,roles);PackingTask task=task(taskId);requireVersion(task,request.version());validateBox(request);Instant now=Instant.now();PackingBox box=boxes.saveAndFlush(new PackingBox(number("BOX"),task,request.weightGrams(),request.lengthMm(),request.widthMm(),request.heightMm(),trim(request.note()),now));saveItems(task,box,request.items(),null);task.touch(now);events.save(new PackingEvent(task,PackingEventType.BOX_ADDED,actor,box.getBoxNo(),now));return response(task);}
    @Transactional public CommandResponse updateBox(Long taskId,Long boxId,SaveBoxRequest request,String subject,List<String> roles){User actor=actor(subject,roles);PackingTask task=task(taskId);requireVersion(task,request.version());PackingBox box=box(boxId,taskId);validateBox(request);Instant now=Instant.now();box.update(request.weightGrams(),request.lengthMm(),request.widthMm(),request.heightMm(),trim(request.note()),now);boxItems.deleteByBoxId(boxId);boxItems.flush();saveItems(task,box,request.items(),boxId);task.touch(now);events.save(new PackingEvent(task,PackingEventType.BOX_UPDATED,actor,box.getBoxNo(),now));return response(task);}
    @Transactional public CommandResponse deleteBox(Long taskId,Long boxId,Long version,String subject,List<String> roles){User actor=actor(subject,roles);PackingTask task=task(taskId);requireVersion(task,version);PackingBox box=box(boxId,taskId);boxItems.deleteByBoxId(boxId);boxes.delete(box);task.touch(Instant.now());events.save(new PackingEvent(task,PackingEventType.BOX_REMOVED,actor,box.getBoxNo(),Instant.now()));return response(task);}
    @Transactional public CommandResponse complete(Long taskId,CompleteRequest request,String subject,List<String> roles){User actor=actor(subject,roles);PackingTask task=tasks.findByIdForUpdate(taskId).orElseThrow(()->notFound("打包任务不存在"));if(task.getStatus()==PackingTaskStatus.COMPLETED&&Objects.equals(task.getCompletionKey(),trim(request.idempotencyKey())))return response(task);requireVersion(task,request.version());if(request.idempotencyKey()==null||request.idempotencyKey().isBlank()||request.idempotencyKey().trim().length()>40)throw bad("幂等键不能为空且不能超过40字符");List<PackingBoxItem> packed=boxItems.findByBoxTaskIdOrderByBoxIdAscIdAsc(taskId);if(packed.isEmpty())throw conflict("PACKING_BOX_EMPTY","至少需要一个有商品的包装箱");List<SalesOrderItem> items=orderItems.findByOrderIdOrderByIdAsc(task.getOrder().getId());for(SalesOrderItem item:items){int sum=packed.stream().filter(i->i.getOrderItem().getId().equals(item.getId())).mapToInt(PackingBoxItem::getQuantity).sum();if(sum!=item.getQuantity())throw conflict("PACKING_QUANTITY_MISMATCH","装箱数量必须等于订单需求");}List<InventoryAllocation> active=allocations.findBySalesOrderItemIdInOrderByIdAsc(items.stream().map(SalesOrderItem::getId).toList()).stream().filter(a->a.getStatus()==InventoryAllocationStatus.RESERVED).toList();for(InventoryAllocation allocation:active){int sum=packed.stream().filter(i->i.getAllocation().getId().equals(allocation.getId())).mapToInt(PackingBoxItem::getQuantity).sum();if(sum!=allocation.getQuantity())throw conflict("PACKING_ALLOCATION_MISMATCH","装箱数量与库存预留不一致");}Instant now=Instant.now();inventory.consume(active.stream().map(InventoryAllocation::getId).toList(),actor,request.idempotencyKey().trim(),now);task.complete(actor,request.idempotencyKey().trim(),now);events.save(new PackingEvent(task,PackingEventType.COMPLETED,actor,"完成打包",now));return response(task);}
    @Transactional public CommandResponse cancel(Long taskId,CancelRequest request,String subject,List<String> roles){User actor=actor(subject,roles);PackingTask task=task(taskId);requireVersion(task,request.version());if(request.reason()==null||request.reason().isBlank())throw bad("取消原因不能为空");task.cancel(actor,trim(request.reason()),Instant.now());events.save(new PackingEvent(task,PackingEventType.CANCELED,actor,trim(request.reason()),Instant.now()));return response(task);}
    private void saveItems(PackingTask task,PackingBox box,List<BoxItemCommand> commands,Long excludedBoxId){if(commands==null||commands.isEmpty())throw bad("包装箱至少包含一个商品");Set<Long> seen=new HashSet<>();for(BoxItemCommand command:commands){if(command.allocationId()==null||command.quantity()==null||command.quantity()<=0||!seen.add(command.allocationId()))throw bad("箱内商品参数无效");InventoryAllocation allocation=allocations.findById(command.allocationId()).orElseThrow(()->notFound("库存分配不存在"));if(!allocation.getSalesOrderItem().getOrder().getId().equals(task.getOrder().getId())||allocation.getStatus()!=InventoryAllocationStatus.RESERVED)throw conflict("PACKING_ALLOCATION_UNAVAILABLE","库存分配不属于当前订单或已不可用");int used=boxItems.findByBoxTaskIdOrderByBoxIdAscIdAsc(task.getId()).stream().filter(i->!Objects.equals(i.getBox().getId(),excludedBoxId)&&i.getAllocation().getId().equals(allocation.getId())).mapToInt(PackingBoxItem::getQuantity).sum();if(used+command.quantity()>allocation.getQuantity())throw conflict("PACKING_ALLOCATION_EXCEEDED","装箱数量超过库存预留");boxItems.save(new PackingBoxItem(box,allocation,command.quantity()));}}
    private void requireFullyReserved(Long orderId){List<SalesOrderItem> items=orderItems.findByOrderIdOrderByIdAsc(orderId);if(items.isEmpty())throw conflict("PACKING_ORDER_EMPTY","订单没有可打包商品");List<InventoryAllocation> all=allocations.findBySalesOrderItemIdInOrderByIdAsc(items.stream().map(SalesOrderItem::getId).toList());for(SalesOrderItem item:items)if(all.stream().filter(a->a.getSalesOrderItem().getId().equals(item.getId())&&a.getStatus()==InventoryAllocationStatus.RESERVED).mapToInt(InventoryAllocation::getQuantity).sum()!=item.getQuantity())throw conflict("PACKING_INVENTORY_INCOMPLETE","订单库存尚未全部预留");}
    private PackingTask task(Long id){PackingTask task=tasks.findByIdForUpdate(id).orElseThrow(()->notFound("打包任务不存在"));if(task.getStatus()!=PackingTaskStatus.DRAFT)throw conflict("PACKING_TASK_IMMUTABLE","已完成或取消的任务不可修改");return task;} private PackingBox box(Long id,Long taskId){PackingBox box=boxes.findById(id).orElseThrow(()->notFound("包装箱不存在"));if(!box.getTask().getId().equals(taskId))throw notFound("包装箱不存在");return box;}
    private User actor(String subject,List<String> roles){if(roles==null||roles.stream().noneMatch(ROLES::contains))throw new ApiException(HttpStatus.FORBIDDEN,"PACKING_FORBIDDEN","无权执行打包操作");try{return users.findById(Long.valueOf(subject)).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"AUTHENTICATION_REQUIRED","登录状态无效"));}catch(NumberFormatException e){throw new ApiException(HttpStatus.UNAUTHORIZED,"AUTHENTICATION_REQUIRED","登录状态无效");}}
    private void validateBox(SaveBoxRequest r){if(r==null||r.version()==null||r.version()<0)throw bad("版本不能为空");if(r.note()!=null&&r.note().trim().length()>500)throw bad("备注不能超过500字符");}
    private void requireVersion(PackingTask task,Long version){if(version==null||task.getVersion()!=version)throw conflict("PACKING_VERSION_CONFLICT","打包任务已更新，请刷新后重试");}
    private CommandResponse response(PackingTask t){tasks.flush();return new CommandResponse(t.getId(),t.getTaskNo(),t.getStatus().name(),t.getVersion());} private String trim(String v){return v==null?null:v.trim();} private String number(String p){return p+"-"+UUID.randomUUID().toString().replace("-","").substring(0,20).toUpperCase();}
    private ApiException bad(String m){return new ApiException(HttpStatus.BAD_REQUEST,"PACKING_REQUEST_INVALID",m);} private ApiException notFound(String m){return new ApiException(HttpStatus.NOT_FOUND,"PACKING_NOT_FOUND",m);} private ApiException conflict(String c,String m){return new ApiException(HttpStatus.CONFLICT,c,m);}
}
